<script setup>
import { computed,onMounted,ref } from 'vue'; import { getForecastData } from '../services/data'; import { calculateProductForecast,statusText } from '../services/inventoryForecast'
const loading=ref(true),error=ref(''),forecasts=ref([]),open=ref(null),detail=ref(null);const fmt=n=>n===null?'—':Number(n).toLocaleString('sl-SI',{maximumFractionDigits:1})
async function load(){loading.value=true;try{const d=await getForecastData();forecasts.value=d.products.filter(p=>p.active).map(product=>{const counts=d.counts.map(c=>({...c,quantity:d.items.find(i=>i.inventory_count_id===c.id&&i.product_id===product.id)?.quantity})).filter(c=>c.quantity!==undefined);const deliveries=d.deliveryItems.filter(i=>i.product_id===product.id).map(i=>({received_at:i.received_at,quantity:i.quantity}));return{product,forecast:calculateProductForecast({counts,deliveries,product,supplier:product.suppliers||{}})}})}catch{error.value='Pregleda ni bilo mogoče naložiti. Poskusite ponovno.'}finally{loading.value=false}}
const groups=computed(()=>({critical:forecasts.value.filter(x=>['critical','out_of_stock'].includes(x.forecast.status)),warning:forecasts.value.filter(x=>x.forecast.status==='warning'),ok:forecasts.value.filter(x=>x.forecast.status==='ok'),unknown:forecasts.value.filter(x=>x.forecast.status==='unknown')}));const labels={critical:'Naroči danes',warning:'Naroči kmalu',ok:'Dovolj zaloge'};onMounted(load)
</script>
<template><section class="page"><header><p class="eyebrow">Sladki kot</p><h1>Pregled zaloge</h1></header><div v-if="loading" class="center-state">Nalagam pregled …</div><p v-else-if="error" class="error">{{error}}</p><template v-else><section v-for="key in ['critical','warning','ok']" :key="key" class="status-group" :class="key"><button class="status-summary" @click="open=open===key?null:key"><span><strong>{{labels[key]}}</strong><small>{{groups[key].length}} artiklov</small></span><ArrowIcon :direction="open===key?'up':'down'" /></button><div v-if="open===key" class="quick-list"><button v-for="item in groups[key]" :key="item.product.id" class="quick-item" @click="detail=item"><span><strong>{{item.product.name}}</strong><small>{{fmt(item.forecast.currentQuantity)}} {{item.product.unit}}</small></span><ArrowIcon direction="right" /></button></div></section><section v-if="groups.unknown.length" class="status-group unknown"><button class="status-summary" @click="open=open==='unknown'?null:'unknown'"><span><strong>Ni dovolj podatkov</strong><small>{{groups.unknown.length}} artiklov</small></span><ArrowIcon :direction="open==='unknown'?'up':'down'" /></button><div v-if="open==='unknown'" class="quick-list"><button v-for="item in groups.unknown" :key="item.product.id" class="quick-item" @click="detail=item"><span><strong>{{item.product.name}}</strong><small>{{fmt(item.forecast.currentQuantity)}} {{item.product.unit}}</small></span><ArrowIcon direction="right" /></button></div></section><div v-if="detail" class="detail-overlay" @click.self="detail=null"><article class="detail-card"><button class="close" @click="detail=null">×</button><p class="eyebrow">{{statusText[detail.forecast.status]}}</p><h2>{{detail.product.name}}</h2><p class="quantity">{{fmt(detail.forecast.currentQuantity)}} {{detail.product.unit}}</p><dl><dt>Poraba</dt><dd>{{detail.forecast.hasEnoughData?`${fmt(detail.forecast.averageDailyUsage)} ${detail.product.unit} / dan`:'Ni dovolj podatkov'}}</dd><dt>Ocena zaloge</dt><dd>{{detail.forecast.daysRemaining===null?'—':`${fmt(detail.forecast.daysRemaining)} dni`}}</dd><dt>Dobavni rok</dt><dd>{{detail.forecast.effectiveLeadTimeDays}} dni</dd><dt>Varnostna zaloga</dt><dd>{{detail.forecast.safetyStockDays}} dni</dd></dl></article></div></template></section></template>
